package br.com.marquesautodetail.api.empresa; import br.com.marquesautodetail.api.empresa.dto.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/empresas") public class EmpresaController{ private final EmpresaService service; public EmpresaController(EmpresaService service){this.service=service;} @GetMapping public List<EmpresaResponse> listar(){return service.listarProximas(null,null);} @GetMapping("/proximas") public List<EmpresaResponse> proximas(@RequestParam Double lat,@RequestParam Double lng){return service.listarProximas(lat,lng);} @GetMapping("/{id}") public EmpresaResponse buscar(@PathVariable Long id){return service.buscarResponse(id);} @PutMapping("/{id}") public EmpresaResponse atualizar(@PathVariable Long id,@RequestBody EmpresaRequest r){return service.atualizar(id,r);} }
